#define entity entity_base
#include "../../../../src/KS/SRC/entity_shared.h"
#undef entity

template<class T>
class my_allocator;

struct random_access_iterator_tag {};

template<class Iterator, class T>
Iterator find(Iterator, Iterator, const T &, random_access_iterator_tag);

template<class Iterator, class T>
inline Iterator find(Iterator first, Iterator last, const T &value)
{
    return find(first, last, value, random_access_iterator_tag());
}

template<class T, class Allocator = my_allocator<T> >
class vector {
public:
    typedef T *iterator;

    iterator start;
    iterator finish;
    iterator end_of_storage;

    iterator begin() { return start; }
    iterator end() { return finish; }
    void _M_insert_aux(iterator, const T &);

    void push_back(const T &value)
    {
        if (finish != end_of_storage) {
            if (finish)
                *finish = value;
            ++finish;
        } else {
            _M_insert_aux(end(), value);
        }
    }
};

class entity : public entity_base {
public:
    bool is_flagged(register unsigned int f) const
    {
        const unsigned int *flags =
            reinterpret_cast<const unsigned int *>(
                reinterpret_cast<const char *>(this) + 0x78);
        return *flags & f;
    }
};

class region {
public:
    typedef vector<entity *> entity_list;

private:
    char data_before_possible_render_ents[0xA0];
    entity_list possible_render_ents;

public:
    void update_poss_render(entity *e);
};

void region::update_poss_render( entity* e )
{
  if(e)
  {
    if(e->is_still_visible() && e->is_flagged(EFLAG_GRAPHICS))
    {
      entity_list::iterator ei_begin = possible_render_ents.begin();
      entity_list::iterator ei_end = possible_render_ents.end();

      entity_list::iterator ei = find( ei_begin, ei_end, e );
      if ( ei == ei_end )
      {
        ei = find( ei_begin, ei_end, (entity*)0 );
        if ( ei != ei_end )
          *ei = e;
        else
        {
          possible_render_ents.push_back( e );
        }
      }
    }
    else
    {
      entity_list::iterator ei_end = possible_render_ents.end();
      entity_list::iterator ei = find( possible_render_ents.begin(), ei_end, e );
      if ( ei != ei_end )
        *ei = 0;
    }
  }
}
